<?php
require dirname(__DIR__) . '/bootstrap.php';
admin_required();
$flash=pull_flash();
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$page=max(1,(int)($_GET['page']??1));$per=12;$offset=($page-1)*$per;
$where=[];$params=[];
if($q!==''){$where[]='(full_name LIKE ? OR employee_code LIKE ? OR designation LIKE ?)';$like="%$q%";$params=[$like,$like,$like];}
if(in_array($status,['pending','approved','rejected'],true)){$where[]='status=?';$params[]=$status;}
$sqlWhere=$where?'WHERE '.implode(' AND ',$where):'';
$count=db()->prepare("SELECT COUNT(*) FROM employees $sqlWhere");$count->execute($params);$total=(int)$count->fetchColumn();
$stmt=db()->prepare("SELECT * FROM employees $sqlWhere ORDER BY created_at DESC LIMIT $per OFFSET $offset");$stmt->execute($params);$employees=$stmt->fetchAll();
$stats=db()->query("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='approved') approved,SUM(status='rejected') rejected FROM employees")->fetch();
$pages=max(1,(int)ceil($total/$per));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><div class="dashboard"><aside class="sidebar"><img src="../assets/img/aryan_gold-logo.png" alt="Aryan Gold"><nav class="nav"><a class="active" href="index.php">Dashboard</a><a href="add.php">Add employee</a><a href="../index.php" target="_blank">Employee form</a></nav><div class="sidebar-bottom"><div style="font-size:12px;color:#cdbbc0;margin-bottom:10px">Signed in as<br><strong style="color:#fff"><?=e($_SESSION['admin_name']??'Administrator')?></strong></div><a class="btn ghost" style="width:100%" href="logout.php">Sign out</a></div></aside><main class="main"><div class="main-head"><div><h1>ID card dashboard</h1><p style="color:var(--muted);margin:6px 0 0">Review submissions and generate employee cards.</p></div><a class="btn primary" href="../index.php" target="_blank">Open public form</a></div><?php if($flash):?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><section class="stats"><div class="stat"><span>Total submissions</span><strong><?=e((string)($stats['total']??0))?></strong></div><div class="stat"><span>Pending review</span><strong><?=e((string)($stats['pending']??0))?></strong></div><div class="stat"><span>Approved</span><strong><?=e((string)($stats['approved']??0))?></strong></div><div class="stat"><span>Rejected</span><strong><?=e((string)($stats['rejected']??0))?></strong></div></section><section class="table-card"><form class="toolbar" method="get"><input name="q" value="<?=e($q)?>" placeholder="Search name, ID or role" style="min-width:260px"><select name="status"><option value="">All statuses</option><?php foreach(['pending','approved','rejected'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><button class="btn ghost small">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Employee ID</th><th>Blood</th><th>Submitted</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$employees):?><tr><td colspan="6" class="empty">No employee submissions found.</td></tr><?php endif;?><?php foreach($employees as $emp):?><tr><td><div class="person-cell"><img class="avatar" src="../<?=e($emp['photo_path'])?>" alt=""><div><strong><?=e($emp['full_name'])?></strong><small><?=e($emp['designation'])?></small></div></div></td><td><?=e($emp['employee_code'])?></td><td><?=e($emp['blood_group'])?></td><td><?=e(date('d M Y',strtotime($emp['created_at'])))?></td><td><span class="badge <?=e($emp['status'])?>"><?=e($emp['status'])?></span></td><td><div class="actions"><a class="btn ghost small" href="view.php?id=<?=$emp['id']?>">View</a><a class="btn gold small" href="card.php?id=<?=$emp['id']?>">Generate ID</a></div></td></tr><?php endforeach;?></tbody></table></div><?php if($pages>1):?><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="?q=<?=urlencode($q)?>&status=<?=urlencode($status)?>&page=<?=$i?>"><?=$i?></a><?php endfor;?></div><?php endif;?></section></main></div><script src="../assets/js/app.js"></script></body></html>
